t1 = t2 = D(0); dif = 0
for ref, r in div.items():
    o = ops[ref]; me, ptax, spr, sp = D(str(o[6])), D(str(o[8])), D(str(o[10])), D(str(o[11]))
    c = D(r["taxa_contratada_pct"]) / 100
    v1 = q((sp - c) * ptax * me); v2 = q(spr - c * ptax * me)
    if r["cnpj"] == "17217888000111":
        t1 += v1; t2 += v2; dif += (v1 != v2)
    if spr < 0: print("NEG", ref, "spreadR$", spr, "saida", r["diferenca_brl"], "v1", v1, "v2", v2)
    assert str(v1) == r["diferenca_brl"], (ref, v1, r["diferenca_brl"])
print("Mundo Aberto: saida(v1)=", t1, " pelo Spread R$ (v2)=", t2, " linhas diferentes:", dif)
